          "document": {
            "version": "schemaxis.gmsh/1",
            "units": "mm",
            "nodes": [
              {
                "id": "solid",
                "filter": "hollowCylinder",
                "options": {
                  "origin": [
                    0,
                    0,
                    0
                  ],
                  "axis": "x",
                  "radius": 4,
                  "innerRadius": 4,
                  "height": 8
                }
              },
              {
                "id": "mesh",
                "filter": "tetrahedral",
                "inputs": {
                  "input": "solid"
                },
                "options": {
                  "size": 0.6,
                  "volumeName": "part",
                  "boundaryName": "wall",
                  "volumeTolerance": 0.02,
                  "faceGroups": [
                    {
                      "name": "start",
                      "axis": "x",
                      "coordinate": 0,
                      "areaTolerance": 0.02
                    },
                    {
                      "name": "end",
                      "axis": "x",
                      "coordinate": 8,
                      "areaTolerance": 0.02
                    }
                  ],
                  "algorithm": "hxt",
                  "optimise": false
                }
              }
            ],
            "output": "mesh"
          },
          "expect": "invalid",
          "fault": "INVALID_ARGUMENT",
          "schemaValid": true
