                      "areaTolerance": 0.02
                    },
                    {
                      "name": "end",
                      "axis": "x",
                      "coordinate": 9,
                      "areaTolerance": 0.02
                    }
                  ],
                  "cylinderGroups": [
                    {
                      "name": "bore",
                      "axis": "x",
                      "centre": [
                        1,
                        2,
                        3
                      ],
                      "radius": 2,
                      "side": "inner"
                    },
                    {
                      "name": "outer",
                      "axis": "x",
                      "centre": [
                        1,
                        2,
                        3
                      ],
                      "radius": 4,
                      "side": "outer"
                    }
                  ]
                }
              }
            ],
            "output": "mesh"
          },
          "expect": "invalid",
          "fault": "INVALID_SELECTION",
          "schemaValid": true
        },
        {
          "id": "wrong-wall-side",
          "document": {
            "version": "schemaxis.gmsh/1",
            "units": "mm",
            "nodes": [
              {
                "id": "solid",
