      "conformance": [
        "tests/unit/test_gmsh_admission.py",
        "tests/unit/test_gmsh_quality.py",
        "tests/unit/test_feedback.py",
        "tests/unit/test_gmsh_primitives.py",
        "tests/unit/test_gmsh_cylinders.py",
        "tests/unit/test_gmsh_cylinder_plan.py"
      ],
      "acceptance": [
        "tools/qualify_gmsh.py",
        "tools/qualify_gmsh_studies.py",
        "tools/qualify_gmsh_primitives.py",
        "tools/qualify_gmsh_cylinders.py"
      ],
      "profiles": {
        "workflow": {
          "scope": "FreeCAD STEP artifact into Gmsh; volume/boundary VTU into ParaView through explicit declared readers. Retain units and name map in the mesh summary.",
          "references": [
            "docs/gmsh.md",
            "tools/qualify_gmsh.py"
          ]
        },
        "composition": {
          "scope": "Shared document references, pure value functions and expressions resolve for every finite analytic visit before native validation.",
          "references": [
            "docs/adaptor-runtime.md",
            "tests/unit/test_adaptor_runtime.py"
          ]
        }
      },
      "development": {
        "api": [
          "https://gmsh.info/doc/texinfo/#Gmsh-API",
          "https://gmsh.info/doc/texinfo/#MSH-file-format-version-2-_0028Legacy_0029",
          "https://gmsh.info/doc/texinfo/#Namespace-gmsh_002fmodel_002focc",
          "https://gmsh.info/doc/texinfo/#Mesh-options",
          "https://gmsh.info/doc/texinfo/#Namespace-gmsh_002fmodel"
        ],
        "lifecycle": {
          "timeout": "One total timeout bounds the two native processes; the shared conformance watchdog also bounds host parsing and cleanup.",
          "cancellation": "Shared owned-process cancellation with retained partial evidence; cancellation is checked before publication.",
          "logs": "Fresh attempt retains authored input, effective plan, captured STEP bytes/digest, worker source, build/reopen stdout/stderr, runtime observations and independently checked publications.",
          "verification": "Fresh Gmsh process reopens MSH. Independent host parser checks positive tetrahedral determinants, full manifold boundary, physical groups, CAD-volume tolerance, bounds and matching VTU connectivity/tags; literal analytic cases check volumes/bounds. Recompute all quality arrays from mesh coordinates and compare native edge extrema. Replay feedback proposals, every verified observation, requirements and stopping decisions; reject altered rejected attempts and chosen publications."
        },
        "data": [
          {
            "id": "step",
            "direction": "input",
            "kind": "cad",
            "format": "STEP ISO-10303-21",
            "traits": {
              "units": "normalised to mm",
              "solids": 1
            },
            "losses": [
              "Feature history and source labels are not retained."
            ],
            "scope": "Single local STEP solid, at most 16 MiB; captured and hashed before import."
          },
          {
            "id": "native-mesh",
            "direction": "output",
            "kind": "mesh",
            "format": "MSH 2.2 ASCII",
            "traits": {
              "units": "mm",
              "cellTypes": [
                "triangle3",
                "tetrahedron4"
              ],
              "physicalGroups": true
            },
            "losses": [
              "Curved CAD becomes piecewise linear.",
              "Authored whole-volume, planar-face and remainder names survive; STEP labels do not."
            ],
            "scope": "One linear solid mesh with physical names embedded; names/units also published in summary."
          },
          {
            "id": "vtk",
            "direction": "output",
            "kind": "geometry",
            "format": "VTU ASCII",
            "traits": {
              "units": "mm",
              "physicalTag": true,
              "qualityArrays": [
                "meanRatio",
                "maximumEdgeLength",
                "volume"
              ]
            },
            "losses": [
              "Separate volume and boundary files contain numeric physicalTag; group names and units require mesh-summary.json.",
              "No CAD history or solver/boundary-condition semantics."
            ],
            "scope": "Loss-declared MSH-to-VTU conversion verified for identical selected coordinates/connectivity/tags; not a general mesh converter."
          }
        ],
        "inspection": [
          {
            "panel": "text",
            "scope": "Inspect summary units, bounds, counts, volumes, names and loss declarations. Inspect quality distributions, declared acceptance checks and selected/rejected candidate history; study.html renders the same independently replayed report. Inspect cylinderChecks (side, unrolled area, chord deviation), cadSurfaces and the group name/tag map in the same text panel.",
            "limits": "Geometry is inspected via published VTU in an external tool (the artifact viewer does not render VTU) or result.msh in Gmsh; no native interactive Gmsh inspector hook."
          }
        ],
        "authoring": {
          "model": "nodes",
          "example": "baseline",
          "reuse": "Edit primitive dimensions/placement, single-solid STEP file, named cap budgets, meshing method or size. Replan in a fresh directory and compare independent analytic/CAD volume, radial containment, group area and quality evidence."
        },
        "features": {
          "workflow": {
            "status": "supported",
            "scope": "FreeCAD STEP artifact into Gmsh; volume/boundary VTU into ParaView through explicit declared readers. Retain units and name map in the mesh summary."
          },
          "native-inspection": {
            "status": "unsupported",
            "scope": "This bounded batch route does not implement native-inspection."
          },
          "composition": {
            "status": "supported",
            "scope": "Shared document references, pure value functions and expressions resolve for every finite analytic visit before native validation."
          },
          "mpi": {
            "status": "unsupported",
            "scope": "This bounded batch route does not implement mpi."
          },
          "reusable-inputs": {
            "status": "supported",
            "scope": "Captured STEP digest changes invalidate reuse; a digest-pinned adopted STEP snapshot ($resource) is accepted by readSTEP; inline typed primitives have no external source. The shared revision checkout/prepare commands accept completed scheduled FreeCAD to Gmsh parents with one native visit per operation, and rerun the child with the edited STEP adopted."
          },
          "time-batches": {
            "status": "unsupported",
            "scope": "This bounded batch route does not implement time-batches."
          },
          "source-authoring": {
            "status": "supported",
            "scope": "Shared revision-bound JSON source editing and undo."
          },
          "property-authoring": {
            "status": "supported",
            "scope": "Shared JSON pointer edits to dimensions, size and physical names."
          },
          "live-editing": {
            "status": "unsupported",
            "scope": "This bounded batch route does not implement live-editing."
          },
          "native-save": {
            "status": "unsupported",
            "scope": "This bounded batch route does not implement native-save."
          },
          "conversion": {
            "status": "supported",
            "scope": "Only the explicit MSH 2.2 linear triangle/tetrahedron to VTU subset described in the data contracts."
          }
        },
